    int n, m;
    while (1) {
        scanf("%d %d", &n, &m);
        if (n == 0 && m == 0) break;

        long long prefix = 0;
        long long best = 0;
        // We store smallest prefix sum modulo m seen so far
        // Since m <= 100000, we can use an array.
        int seen[m];
        for (int i = 0; i < m; i++) seen[i] = -1;
        seen[0] = 0; // prefix sum 0 before first element

        for (int i = 0; i < n; i++) {
            long long k;
            scanf("%lld", &k);
            prefix = (prefix + k) % m;

            // Try to maximize (prefix - seen[?]) mod m
            // We look for smallest remainder >= prefix+1 mod m, but easier:
            // We want max possible (prefix - r + m) % m
            // That is just to check all? m up to 100k, n up to 30k, fine.

            for (int r = 0; r < m; r++) {
                if (seen[r] != -1) {
                    long long rem = (prefix - r + m) % m;
                    if (rem > best) best = rem;
                }
            }

            if (seen[prefix] == -1) {
                seen[prefix] = i+1; // store first occurrence index
            }
        }

        printf("%lld\n", best);
    }
