typedef unsigned long long ull;

int cmp_ull(const void *a, const void *b) {
    ull x = *(ull*)a, y = *(ull*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2 && (n || m)) {
        ull *prefix = (ull*)malloc((n+1)*sizeof(ull));
        prefix[0] = 0;
        for (int i = 1; i <= n; i++) {
            ull k;
            scanf("%llu", &k);
            prefix[i] = (prefix[i-1] + (k % m)) % m;
        }
        // For each j, find best i < j
        // Use sorted array of prefix[0..j-1], query successor of prefix[j]
        ull *sorted = (ull*)malloc((n+1)*sizeof(ull));
        int sz = 0;
        ull ans = 0;
        for (int j = 0; j <= n; j++) {
            ull pj = prefix[j];
            if (sz > 0) {
                // find smallest value > pj
                int lo = 0, hi = sz;
                while (lo < hi) { int mid=(lo+hi)/2; if(sorted[mid]<=pj) lo=mid+1; else hi=mid; }
                if (lo < sz) { ull cand = pj - sorted[lo] + m; if(cand > ans) ans = cand; }
                // find largest value <= pj (for max prefix[j]-prefix[i])
                lo = 0; hi = sz;
                while (lo < hi) { int mid=(lo+hi)/2; if(sorted[mid]<=pj) lo=mid+1; else hi=mid; }
                // lo is first > pj, so lo-1 is last <= pj
                if (lo > 0) { ull cand = pj - sorted[0]; if(cand > ans) ans = cand; }
                // actually minimum is sorted[0]
            }
            // insert pj into sorted
            int pos = 0;
            int lo=0,hi=sz;
            while(lo<hi){int mid=(lo+hi)/2;if(sorted[mid]<pj)lo=mid+1;else hi=mid;}
            pos=lo;
            memmove(sorted+pos+1,sorted+pos,(sz-pos)*sizeof(ull));
            sorted[pos]=pj;
            sz++;
        }
        printf("%llu\n", ans);
        free(prefix); free(sorted);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long long ull;

static int cmp_ull(const void *a, const void *b) {
    ull x = *(const ull *)a;
    ull y = *(const ull *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    ull m;

    while (scanf("%d %llu", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        ull *pref = (ull *)malloc((n + 1) * sizeof(ull));
        ull *mods = (ull *)malloc((n + 1) * sizeof(ull));
        if (!pref || !mods) return 1;

        pref[0] = 0;
        mods[0] = 0;

        for (int i = 1; i <= n; i++) {
            ull x;
            scanf("%llu", &x);
            pref[i] = pref[i - 1] + x;
            mods[i] = pref[i] % m;
        }

        qsort(mods, n + 1, sizeof(ull), cmp_ull);

        ull best = 0;
        for (int i = 1; i <= n; i++) {
            ull diff = mods[i] - mods[i - 1];
            if (diff > best) best = diff;
        }

        ull answer = best;
        if (m - 1 > answer) {
            /* Need wrap-around candidate:
               max over a<b of (mods[a] - mods[b] + m), which is achieved by
               m - minimum positive difference between consecutive sorted mods.
            */
            ull minPosDiff = (ull)-1;
            for (int i = 1; i <= n; i++) {
                ull diff = mods[i] - mods[i - 1];
                if (diff > 0 && diff < minPosDiff) minPosDiff = diff;
            }
            if (minPosDiff != (ull)-1) {
                ull wrap = m - minPosDiff;
                if (wrap > answer) answer = wrap;
            }
        }

        printf("%llu\n", answer);

        free(pref);
        free(mods);
    }

    return 0;
}

