int main() {
    int n;
    long long m;
    while (cin >> n >> m && (n || m)) {
        vector<long long> K(n);
        for (int i = 0; i < n; i++) {
            // Ki can be up to 2^32 - 1, so use unsigned long long
            unsigned long long k;
            cin >> k;
            K[i] = k % m;
        }

        // prefix[i] = (K[0] + ... + K[i-1]) % m
        vector<long long> prefix(n + 1);
        prefix[0] = 0;
        for (int i = 1; i <= n; i++) {
            prefix[i] = (prefix[i-1] + K[i-1]) % m;
        }

        long long ans = 0;
        set<long long> seen;
        seen.insert(prefix[0]);

        for (int j = 1; j <= n; j++) {
            long long pj = prefix[j];

            // Find largest prefix[i] < pj
            auto it = seen.lower_bound(pj);
            if (it != seen.begin()) {
                --it;
                ans = max(ans, pj - *it);
            }

            // Find smallest prefix[i] > pj
            it = seen.upper_bound(pj);
            if (it != seen.end()) {
                ans = max(ans, pj - *it + m);
            }

            seen.insert(pj);
        }

        cout << ans << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;

    while (cin >> n >> m) {
        if (n == 0 && m == 0) break;

        vector<unsigned long long> K(n);
        for (int i = 0; i < n; ++i) cin >> K[i];

        // Prefix sums modulo m.
        // For a subarray sum S, leftover is S % m.
        // We need max subarray sum modulo m.
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = (pref[i] + (long long)(K[i] % (unsigned long long)m)) % m;
        }

        long long ans = 0;
        set<long long> s;
        s.insert(0);

        for (int i = 1; i <= n; ++i) {
            long long x = pref[i];

            // Option 1: subarray from start -> remainder x
            ans = max(ans, x);

            // Option 2: choose previous prefix just larger than x
            // Then (x - y + m) % m = x - y + m, which is maximized this way.
            auto it = s.upper_bound(x);
            if (it != s.end()) {
                ans = max(ans, x - *it + m);
            }

            s.insert(x);
        }

        cout << ans << '\n';
    }

    return 0;
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            if (n == 0 && m == 0) break;
            long[] r = new long[n + 1];
            r[0] = 0;
            StringTokenizer st2 = new StringTokenizer(br.readLine());
            for (int i = 1; i <= n; i++) {
                long k = Long.parseUnsignedLong(st2.nextToken());
                r[i] = (r[i-1] + (k % m)) % m;
            }
            long ans = 0;
            // Case 1
            long minR = r[0];
            for (int j = 1; j <= n; j++) {
                if (r[j] > minR) ans = Math.max(ans, r[j] - minR);
                minR = Math.min(minR, r[j]);
            }
            // Case 2: find min positive (r[i]-r[j]) with i<j, r[i]>r[j]
            long[][] sorted = new long[n+1][2];
            for (int i = 0; i <= n; i++) { sorted[i][0] = r[i]; sorted[i][1] = i; }
            Arrays.sort(sorted, (a,b) -> Long.compare(a[0],b[0]));
            // For adjacent pairs, track min index of larger value
            // Going through sorted order, for each group of same value track min/max index
            // Between adjacent different values v1 < v2: need min_index(v2) < max_index(v1)? No: need some idx_i with r[idx_i]=v2 and some idx_j>idx_i with r[idx_j]=v1
            // i.e., min_index(v2) < max_index(v1)
            int i = 0;
            while (i <= n) {
                int j = i;
                while (j <= n && sorted[j][0] == sorted[i][0]) j++;
                if (j <= n) {
                    long v1 = sorted[i][0], v2 = sorted[j][0];
                    long minIdx2 = Long.MAX_VALUE, maxIdx1 = Long.MIN_VALUE;
                    for (int k = i; k < j; k++) maxIdx1 = Math.max(maxIdx1, sorted[k][1]);
                    for (int k = j; k <= n && sorted[k][0] == v2; k++) minIdx2 = Math.min(minIdx2, sorted[k][1]);
                    if (minIdx2 < maxIdx1) ans = Math.max(ans, m - (v2 - v1));
                }
                i = j;
            }
            System.out.println(ans);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            long nl = fs.nextLong();
            if (nl == Long.MIN_VALUE) break;
            long ml = fs.nextLong();

            int n = (int) nl;
            long m = ml;

            if (n == 0 && m == 0) break;

            long[] prefix = new long[n + 1];
            for (int i = 1; i <= n; i++) {
                long k = fs.nextLong();
                prefix[i] = prefix[i - 1] + k;
            }

            long answer = 0;

            // We need max over subarrays of (sum % m).
            // Let prefix sums be P[0..n]. For subarray (l+1..r):
            // sum = P[r] - P[l]
            // We want max ((P[r] - P[l]) mod m).
            //
            // For each r, consider:
            // 1) choose l with P[l] % m <= P[r] % m, then value is cur - prev
            //    minimized prev gives best => prev = minimum residue seen.
            // 2) choose l with P[l] % m > P[r] % m, then value is cur - prev + m
            //    best is with smallest residue > cur.
            //
            // Maintain seen residues in TreeSet and also global minimum seen residue.

            TreeSet<Long> set = new TreeSet<>();
            set.add(0L);
            long minSeen = 0L;

            for (int i = 1; i <= n; i++) {
                long cur = prefix[i] % m;

                // Case 1: use smallest seen residue <= cur, best is minSeen if minSeen <= cur
                if (minSeen <= cur) {
                    answer = Math.max(answer, cur - minSeen);
                }

                // Case 2: use smallest seen residue > cur
                Long higher = set.higher(cur);
                if (higher != null) {
                    answer = Math.max(answer, cur - higher + m);
                }

                set.add(cur);
                if (cur < minSeen) minSeen = cur;
            }

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}
